@pytest.mark.parametrize("availability,visibility", [
    ("unknown", "visible"), ("unavailable", "visible"), ("observed", "hidden"),
])
def test_required_profiles_and_optional_suppression(helper, snapshot, availability, visibility):
    def mutate(value):
        for row in value["tools"]:
            if row["tool_id"] in ("fixture-cli", "fixture-mcp"):
                row.update(availability=availability, visibility=visibility)
    update(snapshot, helper, "inputs/guidance-profile.json", mutate)
    outputs, guidance, _ = helper._complete_projection(snapshot)
